package com.medicore.inventory.controller;
import com.medicore.inventory.dto.*; import com.medicore.inventory.service.InventoryService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/inventory") public class InventoryController {private final InventoryService service; public InventoryController(InventoryService service){this.service=service;} @PutMapping("/{medicineId}") public InventoryResponse adjust(@PathVariable Long medicineId,@Valid @RequestBody InventoryRequest r){return service.adjust(medicineId,r.quantity());} @PostMapping("/{medicineId}/reserve") public InventoryResponse reserve(@PathVariable Long medicineId,@Valid @RequestBody InventoryRequest r){return service.reserve(medicineId,r.quantity());} @PostMapping("/{medicineId}/release") public InventoryResponse release(@PathVariable Long medicineId,@Valid @RequestBody InventoryRequest r){return service.release(medicineId,r.quantity());}}
